import{_ as n,a0 as r,w as l,s,I as e,x as o,a1 as p,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何在 CentOS 7 上安裝開源 ITIL 門户 iTOP | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 7 上安裝開源 ITIL 門户 iTOP | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 7 上安裝開源 ITIL 門户 iTOP | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 7 上安裝開源 ITIL 門户 iTOP | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150730 How to Setup iTOP (IT Operational Portal) on CentOS 7","title":"如何在 CentOS 7 上安裝開源 ITIL 門户 iTOP","tag":"201509","desc":""},"relativePath":"201509/20150730 How to Setup iTOP (IT Operational Portal) on CentOS 7.md","filePath":"[post].md"}'),m={name:"201509/20150730 How to Setup iTOP (IT Operational Portal) on CentOS 7.md"};function h(c,t,T,g,b,w){const i=r("Link");return l(),s("div",null,[t[16]||(t[16]=e("h1",{id:"如何在-centos-7-上安裝開源-itil-門户-itop",tabindex:"-1"},[o("如何在 CentOS 7 上安裝開源 ITIL 門户 iTOP "),e("a",{class:"header-anchor",href:"#如何在-centos-7-上安裝開源-itil-門户-itop","aria-label":"Permalink to “如何在 CentOS 7 上安裝開源 ITIL 門户 iTOP”"},"​")],-1)),t[17]||(t[17]=e("p",null,"iTOP是一個簡單的基於Web的開源IT服務管理工具。它有所有的ITIL功能，包括服務枱、配置管理、事件管理、問題管理、變更管理和服務管理。iTOP依賴於Apache/IIS、MySQL和PHP，因此它可以運行在任何支持這些軟件的操作系統中。因為iTOP是一個Web程序，因此你不必在用户的PC端任何客户端程序。一個簡單的瀏覽器就足夠每天的IT環境操作了。",-1)),t[18]||(t[18]=e("p",null,"我們要在一台有滿足基本需求的LAMP環境的CentOS 7上安裝和配置iTOP。",-1)),t[19]||(t[19]=e("h3",{id:"下載-itop",tabindex:"-1"},[o("下載 iTOP "),e("a",{class:"header-anchor",href:"#下載-itop","aria-label":"Permalink to “下載 iTOP”"},"​")],-1)),e("p",null,[t[1]||(t[1]=o("iTOP的下載包現在在SourceForge上，我們可以從這獲取它的官方",-1)),p(i,{href:"http://www.combodo.com/spip.php?page=rubrique&id_rubrique=8"},{default:a(()=>[...t[0]||(t[0]=[o("鏈接",-1)])]),_:1}),t[2]||(t[2]=o("。",-1))]),t[20]||(t[20]=d(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/1-itop-download.png" alt="itop download"></p><p>我們從這裏的連接用wget命令獲取壓縮文件。</p><pre><code>[root@centos-007 ~]# wget http://downloads.sourceforge.net/project/itop/itop/2.1.0/iTop-2.1.0-2127.zip
</code></pre><h3 id="itop擴展和網絡安裝" tabindex="-1">iTop擴展和網絡安裝 <a class="header-anchor" href="#itop擴展和網絡安裝" aria-label="Permalink to “iTop擴展和網絡安裝”">​</a></h3><p>使用unzip命令解壓到apache根目錄下的itop文件夾下。</p><pre><code>[root@centos-7 ~]# ls
iTop-2.1.0-2127.zip
[root@centos-7 ~]# unzip iTop-2.1.0-2127.zip -d /var/www/html/itop/
</code></pre><p>列出安裝包中的內容。</p><pre><code>[root@centos-7 ~]# ls -lh /var/www/html/itop/
total 68K
-rw-r--r--. 1 root root 1.4K Dec 17 2014 INSTALL
-rw-r--r--. 1 root root 35K Dec 17 2014 LICENSE
-rw-r--r--. 1 root root 23K Dec 17 2014 README
drwxr-xr-x. 19 root root 4.0K Jul 14 13:10 web
</code></pre><p>這些是我們可以安裝的擴展。</p><pre><code>[root@centos-7 2.x]# ls
authent-external itop-backup itop-config-mgmt itop-problem-mgmt itop-service-mgmt-provider itop-welcome-itil
authent-ldap itop-bridge-virtualization-storage itop-datacenter-mgmt itop-profiles-itil itop-sla-computation version.xml
authent-local itop-change-mgmt itop-endusers-devices itop-request-mgmt itop-storage-mgmt wizard-icons
installation.xml itop-change-mgmt-itil itop-incident-mgmt-itil itop-request-mgmt-itil itop-tickets
itop-attachments itop-config itop-knownerror-mgmt itop-service-mgmt itop-virtualization-mgmt
</code></pre><p>在解壓的目錄下，使用如下的 cp 命令將不同的數據模型從web 下的 datamodels 目錄下複製到 extensions 目錄，來遷移需要的擴展。</p><pre><code>[root@centos-7 2.x]# pwd
/var/www/html/itop/web/datamodels/2.x
[root@centos-7 2.x]# cp -r itop-request-mgmt itop-service-mgmt itop-service-mgmt itop-config itop-change-mgmt /var/www/html/itop/web/extensions/
</code></pre><h3 id="安裝-itop-web界面" tabindex="-1">安裝 iTop web界面 <a class="header-anchor" href="#安裝-itop-web界面" aria-label="Permalink to “安裝 iTop web界面”">​</a></h3><p>大多數服務端設置和配置已經完成了。最後我們安裝web界面來完成安裝。</p><p>打開瀏覽器使用ip地址或者完整域名來訪問iTop 的 web目錄。</p><pre><code>http://servers_ip_address/itop/web/
</code></pre><p>你會被重定向到iTOP的web安裝頁面。讓我們按照要求配置，就像在這篇教程中做的那樣。</p><h4 id="驗證先決要求" tabindex="-1">驗證先決要求 <a class="header-anchor" href="#驗證先決要求" aria-label="Permalink to “驗證先決要求”">​</a></h4><p>這一步你就會看到驗證完成的歡迎界面。如果你看到了一些警告信息，你需要先安裝這些軟件來解決這些問題。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/2-itop-web-install.png" alt="mcrypt missing"></p><p>這一步有一個叫php mcrypt的可選包丟失了。下載下面的rpm包接着嘗試安裝php mcrypt包。</p><pre><code>[root@centos-7 ~]#yum localinstall php-mcrypt-5.3.3-1.el6.x86_64.rpm libmcrypt-2.5.8-9.el6.x86_64.rpm.
</code></pre><p>成功安裝完php-mcrypt後，我們需要重啓apache服務，接着刷新頁面，這時驗證應該已經OK。</p><h4 id="安裝或者升級-itop" tabindex="-1">安裝或者升級 iTop <a class="header-anchor" href="#安裝或者升級-itop" aria-label="Permalink to “安裝或者升級 iTop”">​</a></h4><p>現在我們要在沒有安裝iTOP的服務器上選擇全新安裝。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/3.png" alt="Install New iTop"></p><h4 id="itop-許可協議" tabindex="-1">iTop 許可協議 <a class="header-anchor" href="#itop-許可協議" aria-label="Permalink to “iTop 許可協議”">​</a></h4><p>勾選接受 iTOP所有組件的許可協議，並點擊“NEXT”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/4.png" alt="License Agreement"></p><h4 id="資料庫配置" tabindex="-1">資料庫配置 <a class="header-anchor" href="#資料庫配置" aria-label="Permalink to “資料庫配置”">​</a></h4><p>現在我們輸入資料庫憑據來配置資料庫連接，接着選擇如下選擇創建新資料庫。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/5.png" alt="DB Connection"></p><h4 id="管理員賬户" tabindex="-1">管理員賬户 <a class="header-anchor" href="#管理員賬户" aria-label="Permalink to “管理員賬户”">​</a></h4><p>這一步中我們會輸入它的登錄信息來配置管理員賬户。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/6.png" alt="Admin Account"></p><h4 id="雜項參數" tabindex="-1">雜項參數 <a class="header-anchor" href="#雜項參數" aria-label="Permalink to “雜項參數”">​</a></h4><p>讓我們選擇額外的參數來選擇你是否需要安裝一個帶有演示內容的資料庫或者使用全新的資料庫，接着下一步。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/7.png" alt="Misc Parameters"></p><h3 id="itop-配置管理" tabindex="-1">iTop 配置管理 <a class="header-anchor" href="#itop-配置管理" aria-label="Permalink to “iTop 配置管理”">​</a></h3><p>下面的選項允許你配置在iTOP要管理的元素類型，像CMDB、數據中心設備、存儲設備和虛擬化這些東西在iTOP中是必須的。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/8.png" alt="Conf Management"></p><h4 id="服務管理" tabindex="-1">服務管理 <a class="header-anchor" href="#服務管理" aria-label="Permalink to “服務管理”">​</a></h4><p>選擇一個最能描述你的IT設備和環境之間的關係的選項。因此我們這裏選擇為服務提供商的服務管理。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/9.png" alt="Service Management"></p><h4 id="itop-tickets-管理" tabindex="-1">iTop Tickets 管理 <a class="header-anchor" href="#itop-tickets-管理" aria-label="Permalink to “iTop Tickets 管理”">​</a></h4><p>從不同的可用選項我們選擇符合ITIL Tickets管理選項來管理不同類型的用户請求和事件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/10.png" alt="Ticket Management"></p><h4 id="改變管理選項" tabindex="-1">改變管理選項 <a class="header-anchor" href="#改變管理選項" aria-label="Permalink to “改變管理選項”">​</a></h4><p>選擇不同的ticket類型以便管理可用選項中的IT設備變更。我們選擇ITTL變更管理選項。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/11.png" alt="ITIL Change"></p><h4 id="itop-擴展" tabindex="-1">iTop 擴展 <a class="header-anchor" href="#itop-擴展" aria-label="Permalink to “iTop 擴展”">​</a></h4><p>這一節我們選擇額外的擴展來安裝或者不選直接跳過。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/13.png" alt="iTop Extensions"></p><h3 id="準備開始web安裝" tabindex="-1">準備開始web安裝 <a class="header-anchor" href="#準備開始web安裝" aria-label="Permalink to “準備開始web安裝”">​</a></h3><p>現在我們開始準備安裝先前先前選擇的組件。我們也可以下拉這些安裝參數來瀏覽我們的配置。</p><p>確認安裝參數後點擊安裝按鈕。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/16.png" alt="Installation Parameters"></p><p>讓我們等待進度條來完成安裝步驟。它也許會花費幾分鐘來完成安裝步驟。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/17.png" alt="iTop Installation Process"></p><h3 id="itop安裝完成" tabindex="-1">iTop安裝完成 <a class="header-anchor" href="#itop安裝完成" aria-label="Permalink to “iTop安裝完成”">​</a></h3><p>我們的iTOP安裝已經完成了，只要如下一個簡單的手動操作就可以進入到iTOP。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/18.png" alt="iTop Done"></p><h3 id="歡迎來到itop-it操作門户" tabindex="-1">歡迎來到iTop (IT操作門户) <a class="header-anchor" href="#歡迎來到itop-it操作門户" aria-label="Permalink to “歡迎來到iTop (IT操作門户)”">​</a></h3><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/20.png" alt="itop welcome note"></p><h3 id="itop-面板" tabindex="-1">iTop 面板 <a class="header-anchor" href="#itop-面板" aria-label="Permalink to “iTop 面板”">​</a></h3><p>你這裏可以配置任何東西，服務、計算機、通訊錄、位置、合同、網絡設備等等。你可以創建你自己的。事實是剛安裝的CMDB模組是每一個IT人員的必備模組。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/19.png" alt="iTop Dashboard"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>ITOP是一個最棒的開源桌面服務解決方案。我們已經在CentOS 7上成功地安裝和配置了。因此，iTOP最強大的一方面是它可以很簡單地通過擴展來自定義。如果你在安裝中遇到任何問題歡迎評論。</p><hr>`,70)),e("p",null,[t[4]||(t[4]=o("via: ",-1)),p(i,{href:"http://linoxide.com/tools/setup-itop-centos-7/"},{default:a(()=>[...t[3]||(t[3]=[o("http://linoxide.com/tools/setup-itop-centos-7/",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=o("作者：",-1)),p(i,{href:"http://linoxide.com/author/kashifs/"},{default:a(()=>[...t[5]||(t[5]=[o("Kashif Siddique",-1)])]),_:1}),t[9]||(t[9]=o(" 譯者：",-1)),p(i,{href:"https://github.com/geekpi"},{default:a(()=>[...t[6]||(t[6]=[o("geekpi",-1)])]),_:1}),t[10]||(t[10]=o(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[7]||(t[7]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=o("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[o("LCTT",-1)])]),_:1}),t[14]||(t[14]=o(" 原創翻譯，",-1)),p(i,{href:"https://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[o("Linux中國",-1)])]),_:1}),t[15]||(t[15]=o(" 榮譽推出",-1))])])}const f=n(m,[["render",h]]);export{P as __pageData,f as default};
